<script setup lang="ts">
import HelpHint from './HelpHint.vue'
import SpeechVocabulary from './SpeechVocabulary.vue'
import {ref,watch,onBeforeUnmount,computed} from 'vue'
import {Editor,EditorContent} from '@tiptap/vue-3'
import MultiSelect from 'primevue/multiselect'
import StarterKit from '@tiptap/starter-kit'
import {TableKit} from '@tiptap/extension-table'
import {Placeholder,ClinicalSection} from './placeholder'
import {clone,api,newField,type Template,type Field} from './api'
import {money} from './billing'
import SectionDesigner from './SectionDesigner.vue'
import DocumentToolbar from './DocumentToolbar.vue'
import {DocumentAlignment} from './documentFormatting'
const props=defineProps<{template:Template,specialties?:string[],templateLimitReached?:boolean,addonQuote?:{plan_version:string,monthly_minor:number,currency:string},copyFromLibrary?:boolean}>()
const emit=defineEmits<{saved:[Template],error:[string]}>()
const draft=ref<Template>(clone(props.template)),selected=ref<Field|null>(null),advanced=ref(false),source=ref(''),ruleJSON=ref('[]'),sectionJSON=ref('[]'),fragmentJSON=ref('{}'),saving=ref(false),fragmentNotice=ref(''),report=ref(''),proposals=ref<any[]>([]),proposing=ref(false)
const selectedSpecialties=computed({
  get:()=>draft.value.specialties??[draft.value.specialty].filter(Boolean),
  set:(values:string[])=>{
    draft.value.specialties=values
    draft.value.specialty=values[0]||''
  }
})
const extraTemplatePrice=computed(()=>props.addonQuote?money(props.addonQuote.monthly_minor,props.addonQuote.currency):'')
let addonRequestID=''
const editor=new Editor({extensions:[StarterKit.configure({heading:{levels:[1,2,3]},link:false,code:false,codeBlock:false}),TableKit,DocumentAlignment,Placeholder,ClinicalSection],content:'',editorProps:{attributes:{role:'textbox','aria-label':'Conținutul șablonului','aria-multiline':'true','data-placeholder':'Scrie aici textul șablonului…'}},onSelectionUpdate:({editor})=>{const a=editor.getAttributes('placeholder');if(a.field)selected.value=draft.value.fields.find(f=>f.key===a.field)||null}})
function load(){fragmentNotice.value='';addonRequestID='';draft.value=clone(props.template);if(props.specialties?.length){
  selectedSpecialties.value=selectedSpecialties.value.filter(s=>props.specialties?.includes(s))
}draft.value.generation_id=undefined;draft.value.ai_context??={instructions:'',terminology:'',examples:''};source.value=draft.value.html.replace(/\{\{([a-z][a-z0-9_]*)\}\}/g,(_,key)=>`<span data-field="${key}">${draft.value.fields.find(f=>f.key===key)?.label||key}</span>`);editor.commands.setContent(source.value);ruleJSON.value=JSON.stringify(draft.value.rules||[],null,2);sectionJSON.value=JSON.stringify(draft.value.sections||[],null,2);fragmentJSON.value=JSON.stringify(draft.value.fragments||{},null,2);selected.value=null}
watch(()=>props.template,load,{immediate:true})
watch(()=>draft.value.sections,value=>{sectionJSON.value=JSON.stringify(value,null,2)},{deep:true})
onBeforeUnmount(()=>editor.destroy())
function insert(f:Field){selected.value=f;editor.chain().focus().insertContent({type:'placeholder',attrs:{field:f.key,label:f.label}}).run()}
function add(){const f=newField();draft.value.fields.push(f);insert(f)}
function selectField(f:Field){selected.value=f}
function renameKey(value:string|undefined){if(!selected.value||!value)return;const old=selected.value.key;selected.value.key=value;editor.state.doc.descendants((node,pos)=>{if(node.type.name==='placeholder'&&node.attrs.field===old)editor.commands.command(({tr})=>{tr.setNodeMarkup(pos,undefined,{...node.attrs,field:value});return true})});source.value=source.value.split(`data-field="${old}"`).join(`data-field="${value}"`).split('{{'+old+'}}').join('{{'+value+'}}');try{const rules=JSON.parse(ruleJSON.value);for(const r of rules){if(r.field===old)r.field=value;if(r.required_field===old)r.required_field=value};ruleJSON.value=JSON.stringify(rules,null,2);const sections=JSON.parse(sectionJSON.value);for(const section of sections){if(section.condition_field===old)section.condition_field=value};sectionJSON.value=JSON.stringify(sections,null,2)}catch{};if(draft.value.semantic_mapping?.[old]){draft.value.semantic_mapping[value]=draft.value.semantic_mapping[old];delete draft.value.semantic_mapping[old]}}
function rename(){if(!selected.value)return;editor.state.doc.descendants((node,pos)=>{if(node.type.name==='placeholder'&&node.attrs.field===selected.value?.key)editor.commands.command(({tr})=>{tr.setNodeMarkup(pos,undefined,{...node.attrs,label:selected.value?.label});return true})})}
async function save(copy=false){saving.value=true;try{if(!draft.value.specialty)throw new Error('Selectează cel puțin o specialitate.');if(draft.value.name.trim().length<2)throw new Error('Introduceți un nume de șablon de minimum două caractere.');const keys=new Set<string>();for(const f of draft.value.fields){if(!/^[a-z][a-z0-9_]{0,63}$/.test(f.key)||keys.has(f.key)||!f.label.trim())throw new Error('Câmpurile trebuie să aibă identificatori unici valizi și etichete.');keys.add(f.key);if(typeof f.min!=='number')f.min=null;if(typeof f.max!=='number')f.max=null;if(f.min!==null&&f.max!==null&&f.min>f.max)throw new Error('Limita minimă trebuie să fie mai mică decât limita maximă.')}draft.value.html=advanced.value?source.value:editor.getHTML();draft.value.rules=JSON.parse(ruleJSON.value);draft.value.sections=JSON.parse(sectionJSON.value);draft.value.fragments=JSON.parse(fragmentJSON.value);const payload=clone(draft.value);if(copy){payload.id='';payload.name+=' · copie'};const needsAddon=props.templateLimitReached&&(!payload.id||props.copyFromLibrary)
if(needsAddon){
  const quote=props.addonQuote
  if(!quote||!window.confirm('Adaugi acest șablon pentru '+extraTemplatePrice.value+' pe lună? Prima lună se facturează integral, cu reînnoire la începutul fiecărei luni UTC. Termen de plată: 5 zile.'))return
  addonRequestID||=crypto.randomUUID()
  const t=await api<Template>('templates','POST',{...payload,addon_confirmation:{plan_version:quote.plan_version,monthly_minor:quote.monthly_minor,request_id:addonRequestID}})
  emit('saved',t)
}else{
  const t=await api<Template>('templates','POST',payload)
  emit('saved',t.id===props.template.id?{...t,addon_monthly_minor:props.template.addon_monthly_minor,addon_currency:props.template.addon_currency,addon_ends_at:props.template.addon_ends_at}:t)
}}catch(e){emit('error',String(e))}finally{saving.value=false}}
async function propose(){proposing.value=true;try{const result=await api('templates/proposals','POST',{report:report.value});proposals.value=result.fields;draft.value.generation_id=result.generation_id}catch(e){emit('error',String(e))}finally{proposing.value=false}}
function acceptProposals(){for(const suggestion of proposals.value){if(!draft.value.fields.some(f=>f.key===suggestion.key)){const f={...newField(),key:suggestion.key,label:suggestion.label,type:suggestion.type,unit:suggestion.unit};draft.value.fields.push(f);insert(f)}};proposals.value=[];report.value=''}
function insertFragment(key:string){
  fragmentNotice.value=''
  try{
    const fragments=JSON.parse(fragmentJSON.value)
    if(typeof fragments?.[key]!=='string'||!fragments[key].trim()){
      fragmentNotice.value='Fragmentul „'+key+'” nu este definit. Configurează textul în „Reguli, secțiuni și fragmente” → „Fragmente normal/patologic”.'
      return
    }
    editor.chain().focus().insertContent(fragments[key]).run()
  }catch{fragmentNotice.value='Fragmentele nu au un format JSON valid. Verifică obiectul cu cheile normal și patologic din „Reguli, secțiuni și fragmente”.'}
}
function composeStructure(){const escape=(text:string)=>text.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');const seen=new Set<string>();function render(parent:string):string{return draft.value.sections.filter(s=>s.parent===parent).map(s=>{if(seen.has(s.id))throw new Error('Secțiuni cu dependență circulară.');seen.add(s.id);return '<section data-section="'+escape(s.id)+'"><h3>'+escape(s.label)+'</h3>'+draft.value.fields.filter(f=>f.section===s.id).map(f=>'<p>'+escape(f.label)+': <span data-field="'+escape(f.key)+'">'+escape(f.label)+'</span>'+(f.unit?' '+escape(f.unit):'')+'</p>').join('')+render(s.id)+'</section>'}).join('')};const html='<h2>'+escape(draft.value.name)+'</h2>'+render('')+draft.value.fields.filter(f=>!f.section).map(f=>'<p>'+escape(f.label)+': <span data-field="'+escape(f.key)+'">'+escape(f.label)+'</span></p>').join('');editor.commands.setContent(html);source.value=html;advanced.value=false}
function toggleSource(){if(!advanced.value)source.value=editor.getHTML();else editor.commands.setContent(source.value);advanced.value=!advanced.value}
</script>
<template>
<div class="editor-head"><div><span class="eyebrow">VERSIUNI IMUTABILE</span><h2>Editor de șablon<HelpHint topic="publish"/></h2><p>Publicarea creează o versiune nouă. Sesiunile existente păstrează versiunea lor.</p></div><div class="actions"><Button v-if="draft.id && !copyFromLibrary" label="Copiază" severity="secondary" @click="save(true)" :loading="saving" :disabled="templateLimitReached&&!addonQuote"/><Button :label="copyFromLibrary?'Adaugă la șabloanele mele':'Publică versiune'" icon="pi pi-check" @click="save()" :loading="saving" :disabled="templateLimitReached&&!addonQuote&&(!draft.id||copyFromLibrary)"/></div></div>
<Message v-if="templateLimitReached" severity="warn">
  Ai atins limita de șabloane proprii.
  <template v-if="extraTemplatePrice"> Un șablon suplimentar costă {{extraTemplatePrice}} pe lună. Vei confirma costul înainte de adăugare.</template>
  <template v-else> Contactează administratorul pentru un loc suplimentar.</template>
</Message>
<Message v-if="draft.addon_monthly_minor && draft.addon_currency" severity="info">
  Șablon suplimentar · {{money(draft.addon_monthly_minor,draft.addon_currency)}} / lună.
  <span v-if="draft.addon_ends_at">Reînnoire oprită. Acces până la {{new Date(draft.addon_ends_at).toLocaleDateString('ro-RO',{timeZone:'UTC'})}} (UTC).</span>
  <span v-else> Poți opri reînnoirea din Pachetul meu.</span>
</Message>
<div class="form-row"><label><span class="help-label">Nume<HelpHint topic="name"/></span><InputText v-model="draft.name"/></label><label><span class="help-label">Specialități<HelpHint topic="specialties"/></span><MultiSelect v-if="specialties?.length" v-model="selectedSpecialties" :options="specialties" display="chip" filter placeholder="Alege specialitățile"/><InputText v-else v-model="draft.specialty"/></label></div>
<div class="editor-grid"><section class="paper editor-paper">
  <div class="document-editor-heading"><div><h3><i class="pi pi-file-edit" aria-hidden="true"/> Conținutul șablonului<HelpHint topic="editing"/></h3><p>Apasă în document și scrie sau modifică textul direct. Selectează textul pentru formatare.</p></div><span class="document-mode">{{advanced?'Sursă HTML':'Text editabil · WYSIWYG'}}</span></div>
  <div class="document-mode-tools"><Button :label="advanced?'Revino la editorul vizual':'Editează sursa HTML'" :icon="advanced?'pi pi-pencil':'pi pi-code'" text size="small" @click="toggleSource"/><HelpHint topic="html"/><Button v-if="!advanced" label="Scrie în document" icon="pi pi-pencil" size="small" severity="secondary" @click="editor.chain().focus().run()"/></div>
  <DocumentToolbar :editor="editor" :disabled="advanced"/>
  <div class="document-insert-tools" role="group" aria-label="Inserează în șablon"><span>Inserează:</span><Button label="Câmp" icon="pi pi-plus" size="small" :disabled="advanced" @click="add"/><HelpHint topic="fields"/><Button label="Fragment normal" size="small" text :disabled="advanced" @click="insertFragment('normal')"/><Button label="Fragment patologic" size="small" text :disabled="advanced" @click="insertFragment('patologic')"/><HelpHint topic="fragments"/></div>
  <Message v-if="fragmentNotice" severity="info" class="fragment-notice">{{fragmentNotice}}</Message>
  <Textarea v-if="advanced" v-model="source" rows="18" class="code document-source" aria-label="Sursă HTML"/><EditorContent v-else :editor="editor"/>
  <p class="muted small document-editor-footer">Textul se editează liber; pastilele verzi reprezintă câmpuri completate din dictare. Modificările se salvează prin publicarea unei versiuni.<br/>Variabile disponibile: &#123;&#123;patient_ref&#125;&#125;, &#123;&#123;doctor_name&#125;&#125;.</p>
</section>
<aside class="paper"><h3>Câmpuri structurate<HelpHint topic="fields"/></h3><p class="muted">Selectați un câmp pentru configurare.</p><div class="field-list"><button v-for="f in draft.fields" :key="f.key" @click="selectField(f)" :class="{active:selected?.key===f.key}"><span>{{f.label}} <b v-if="f.required">*</b></span><i aria-hidden="true" :class="f.invisible?'pi pi-eye-slash':'pi pi-angle-right'"></i></button></div><Button label="Adaugă un câmp" :disabled="advanced" text icon="pi pi-plus" @click="add"/>
<template v-if="selected"><hr/><p v-if="selected.help" class="field-help">{{selected.help}}</p><label><span class="help-label">Identificator<HelpHint topic="key"/></span><InputText :modelValue="selected.key" @update:modelValue="renameKey" pattern="[a-z][a-z0-9_]*"/></label><label><span class="help-label">Etichetă<HelpHint topic="label"/></span><InputText v-model="selected.label" @update:modelValue="rename"/></label><label><span class="help-label">Tip<HelpHint topic="type"/></span><Select v-model="selected.type" :options="['string','number','boolean']"/></label><label><span class="help-label">Unitate<HelpHint topic="unit"/></span><InputText v-model="selected.unit"/></label><div class="form-row"><label><span class="help-label">Min<HelpHint topic="min"/></span><input type="number" v-model.number="selected.min"/></label><label><span class="help-label">Max<HelpHint topic="max"/></span><input type="number" v-model.number="selected.max"/></label></div><label><span class="help-label">Aliasuri (virgulă)<HelpHint topic="aliases"/></span><InputText :modelValue="selected.aliases?.join(', ')" @update:modelValue="selected.aliases=($event||'').split(',').map(x=>x.trim()).filter(Boolean)"/></label><label><span class="help-label">Semantic tag<HelpHint topic="semantic"/></span><InputText v-model="selected.semantic_tag"/></label><label><span class="help-label">Explicație pentru completare<HelpHint topic="fieldHelp"/></span><Textarea v-model="selected.help" rows="2"/></label><label><span class="help-label">Secțiune<HelpHint topic="fieldSection"/></span><Select v-model="selected.section" :options="[{id:'',label:'Fără secțiune'},...draft.sections]" optionLabel="label" optionValue="id"/></label><label class="check"><input type="checkbox" v-model="selected.required"/> <span class="help-label">Obligatoriu<HelpHint topic="required"/></span></label><label class="check"><input type="checkbox" v-model="selected.invisible"/> <span class="help-label">Invizibil în document<HelpHint topic="invisible"/></span></label><label class="check"><input type="checkbox" v-model="selected.repeatable"/> <span class="help-label">Repetabil<HelpHint topic="repeatable"/></span></label><Button label="Inserează în document" :disabled="advanced" size="small" @click="insert(selected)"/><HelpHint topic="insert"/></template></aside></div>
<SectionDesigner v-model="draft.sections" :fields="draft.fields" @compose="composeStructure"/><label><span class="help-label">Nivel de detaliu implicit al șablonului<HelpHint topic="detail"/></span><Select v-model="draft.default_detail" :options="[{label:'Scurt',value:'brief'},{label:'Standard',value:'standard'},{label:'Detaliat',value:'detailed'}]" optionLabel="label" optionValue="value"/></label><details class="paper"><summary>Context AI al șablonului · memorie persistentă<HelpHint topic="context"/></summary><p class="muted small">Salvat în PostgreSQL, criptat și legat de versiunea publicată. Include reguli, terminologie și exemple anonimizate, fără date despre pacienți. Nu este istoric de pacient și nu înlocuiește dovezile din transcriere.</p><template v-if="draft.ai_context"><label><span class="help-label">Reguli de completare<HelpHint topic="instructions"/></span><Textarea v-model="draft.ai_context.instructions" rows="4" maxlength="2000" placeholder="Descrie cum trebuie documentate câmpurile, fără a inventa valori."/></label><label><span class="help-label">Terminologie și abrevieri<HelpHint topic="terminology"/></span><Textarea v-model="draft.ai_context.terminology" rows="3" maxlength="1500"/></label><label><span class="help-label">Exemple anonimizate acceptate<HelpHint topic="examples"/></span><Textarea v-model="draft.ai_context.examples" rows="4" maxlength="2000"/></label></template><p class="muted small">Contextul este trimis modelului când se extrag date pentru acest șablon; contribuie la tokenurile de intrare. O modificare devine activă numai la publicarea unei versiuni noi.</p></details><details class="paper"><summary>Propune câmpuri dintr-un raport existent<HelpHint topic="proposals"/></summary><p>Raportul este procesat de providerul configurat. Propunerile nu modifică șablonul până la acceptare. Eliminați identificatorii pacientului înainte de trimitere.</p><label><span class="help-label">Raport de referință<HelpHint topic="report"/></span><Textarea v-model="report" rows="6" maxlength="20000" placeholder="Ficat: descriere
Splină: descriere"/></label><Button label="Propune câmpuri" icon="pi pi-sparkles" @click="propose" :loading="proposing" :disabled="report.length<5"/><div v-if="proposals.length"><div v-for="p in proposals" class="record"><b>{{p.label}} · {{p.key}} · {{p.type}}</b><p>„{{p.quote}}”</p></div><Button label="Acceptă propunerile în editor" icon="pi pi-check" @click="acceptProposals"/><HelpHint topic="accept"/></div></details>
<details class="paper"><summary>Reguli, secțiuni și fragmente<HelpHint topic="json"/></summary><p>Regulă: {"field":"cheie","equals":"valoare","required_field":"cheie"}. Secțiune: id, label, parent, condition_field, condition_value, repeatable. Regulile sunt declarative.</p><div class="three"><label><span class="help-label">Reguli JSON<HelpHint topic="rules"/></span><Textarea v-model="ruleJSON" rows="7" class="code"/></label><label><span class="help-label">Secțiuni JSON<HelpHint topic="sectionsJSON"/></span><Textarea v-model="sectionJSON" rows="7" class="code"/></label><label><span class="help-label">Fragmente normal/patologic<HelpHint topic="fragments"/></span><Textarea v-model="fragmentJSON" rows="7" class="code" aria-label="Fragmente normal/patologic" aria-describedby="fragment-description"/><span id="fragment-description" class="muted small">Texte reutilizabile inserate manual la cursor. Definește cheile JSON normal și patologic. Nu sunt selectate automat după dictare; pentru asta folosește variantele secțiunii.</span></label></div></details>
<SpeechVocabulary v-if="template.id" :key="template.version_id" :template="template" @error="emit('error',$event)"/>
</template>
